args.command:
node --input-type=module <<'EOF'
import { permit } from './limit.mjs';
const cases = [
  ['-1', -1, false],
  ['0', 0, true],
  ['3', 3, true],
  ['4', 4, false],
  ['string "3"', '3', false],
  ['null', null, false],
  ['NaN', NaN, false],
  ['fraction 1.5', 1.5, false],
  ['undefined', undefined, false],
  ['Infinity', Infinity, false],
  ['-Infinity', -Infinity, false],
];
let failures = 0;
for (const [label, input, expected] of cases) {
  const actual = permit(input);
  const pass = Object.is(actual, expected);
  console.log(`${pass ? 'PASS' : 'FAIL'} ${label}: permit(${label}) => ${actual}; expected ${expected}`);
  if (!pass) failures++;
}
if (failures) process.exit(1);
EOF
